document.addEventListener("DOMContentLoaded",function(){console.log("Services page specific JavaScript loaded and executing.");const initializeStickyHover=(gridElement,index)=>{const cards=gridElement.querySelectorAll(".service-tier");if(cards.length===0){return}const middleIndex=Math.floor(cards.length/2);cards[middleIndex].classList.add("active");console.log(`Initialized sticky hover for grid ${index+1}, activated middle card (index ${middleIndex}).`);cards.forEach(card=>{card.addEventListener("mouseenter",()=>{cards.forEach(c=>c.classList.remove("active"));card.classList.add("active")})})};const serviceGrids=document.querySelectorAll(".services-grid");serviceGrids.forEach(initializeStickyHover);const addonCards=document.querySelectorAll(".addon-card");addonCards.forEach(card=>{card.addEventListener("mouseenter",()=>{card.style.transform="translateY(-5px)"});card.addEventListener("mouseleave",()=>{card.style.transform="translateY(0)"})});const links=document.querySelectorAll('a[href^="#"]');links.forEach(link=>{link.addEventListener("click",function(e){const targetId=this.getAttribute("href");if(targetId.length>1&&targetId.startsWith("#")){const targetElement=document.getElementById(targetId.substring(1));if(targetElement){e.preventDefault();targetElement.scrollIntoView({behavior:"smooth"})}}})});const assessmentFormContainer=document.getElementById("assessment-form-container");const revealTriggers=document.querySelectorAll(".reveal-assessment-trigger");if(revealTriggers.length>0&&assessmentFormContainer){revealTriggers.forEach(trigger=>{trigger.addEventListener("click",function(e){e.preventDefault();const service=this.getAttribute("data-service");assessmentFormContainer.style.display="block";assessmentFormContainer.scrollIntoView({behavior:"smooth"});const serviceDropdown=assessmentFormContainer.querySelector("#cta-service-dropdown-trigger");const serviceInput=assessmentFormContainer.querySelector("#primary-service");const serviceLabel=assessmentFormContainer.querySelector("#cta-service-label");if(serviceDropdown&&serviceInput&&serviceLabel){serviceInput.value=service;serviceLabel.textContent=service}})})}});